package io.github.diodeme.ji.remote;

import java.util.Optional;

/** Remote facts used to select and safely activate a private Host bundle. */
public record RemoteProbe(
        String os, String architecture, String home, long availableBytes, Optional<String> currentVersion) {
    public RemoteProbe {
        if (os == null || os.isBlank() || architecture == null || architecture.isBlank()
                || home == null || home.isBlank() || availableBytes < 0) {
            throw new IllegalArgumentException("invalid remote probe");
        }
        currentVersion = currentVersion == null ? Optional.empty() : currentVersion;
    }
}
